-- wave-clean-b-2026-10-08: 195 field(s) in one DO block, one UPDATE per column.
-- Each UPDATE must change exactly the number of rows it lists; if one does not, the whole block rolls back.
-- Generated 2026-10-08 by scripts/copy/build-copy-sql.mjs. Guards: md5 of the current text; every literal is ASCII.
do $apply$
declare n int;
begin
  update venues v set why_its_here = d.val
  from (values
    ('le-meridien-bali-jimbaran-fitness', '6146f723dcf615c771d3e66d962de67e', U&'Le M\00E9ridien Bali Jimbaran''s gym is open 24 hours and free to hotel guests. It has cardio machines, exercise bikes, treadmills, free weights and weight machines, and Explore Spa is on the same property.'),
    ('lkp-tirtasari-spa-tabanan', '0d0c3fde5833797a39d390233be10076', 'In Tabanan, LKP Tirtasari Spa does Balinese massage, and you book it by WhatsApp.'),
    ('lluvia-spa-seminyak', '7495f5cbd3773f6c7a1e6a50735c08eb', 'Lluvia Spa in Seminyak does head massage: its Japanese Head Spa is 90 minutes for 399K IDR.'),
    ('luigis-hot-pizza', '309e4ab5b4c1d41bbae4173039e22540', 'A big, loud Neapolitan pizza place on Jl. Batu Mejan, built out of shipping containers. The wood-fired oven was imported from Napoli, and there are party nights every week.'),
    ('luna-and-sol-pilates-yoga', '0172806fa7c913396d215537cc3cf7fe', 'Luna & Sol teaches pilates on Jl. Raya Semat, with classes on the reformer, chair and springboard as well as the mat, plus yoga. Levels mix beginner and intermediate, and some classes also run on Zoom.'),
    ('luxme-bali-jimbaran', 'bb74a9b44547a8759e9552bd164c137a', 'LuxMe Bali is a spa in Jimbaran that does four hands massage.'),
    ('luxury-spa-nusa-dua', '1e6c513472ba62a011b75e4b749ef1a0', 'Luxury Spa is a Nusa Dua day spa that does pilates. You book through its website.'),
    ('m-boutique-resort-uluwatu-bukit', '277fec3bbfb20a2ed49a0ef6538a4364', U&'M\00FB Boutique Resort in the Bukit runs yoga at its spa. Bookings go through the resort''s website.'),
    ('mandapa-fitness-centre', '64ed8e83a557d685625531c2089c8d5a', 'Mandapa, a Ritz-Carlton Reserve in the Ayung river valley near Ubud, has a 24-hour fitness centre that resort guests use free. The Mandapa Spa & Wellness Centre sits alongside it, with yoga in a river-facing pavilion and on platforms over the rice terraces.'),
    ('mantra-wellness-bali-uluwatu-bukit', '9ecfd736bdc4a4a1b1d8534105c61077', 'Mantra Wellness Bali is a wellness spa in the Bukit with Balinese and traditional massage, plus yoga. You book on its website.'),
    ('mapogu-coffee-and-eatery-mapogu-restaurant', '98b379a651b4a044fea08eadcab89aae', 'Mapogu is a cafe and coworking space in Goa Gong, Jimbaran, open since 2022. The kitchen mixes Korean-leaning dishes with Indonesian and international plates. Wifi is free, there is parking, and live music plays at weekends.'),
    ('massimo-italian-restaurant', 'a214849f93f78492d3b5fe6678a3e4c9', 'An Italian restaurant on Jalan Danau Tamblingan, Sanur''s main strip. Pasta, mozzarella, burrata and gelato are made in-house daily, and the pizza is wood-fired and naturally leavened. The owner has made Italian gelato in Sanur since 1996, with 48+ flavours.'),
    ('maya-sanur-fitness-centre', '2cb5eef9de26c45b4635d16f3bf941f4', 'Maya Sanur Resort & Spa has an air-conditioned fitness centre with cardio and strength machines, free for in-house guests. The property is beachfront, with the resort''s long lagoon pool and four restaurants.'),
    ('maya-ubud-fitness-centre-ubud', '0926c7ea4953a378d3b82b9f0651724a', 'Maya Ubud Resort & Spa sits on the Peliatan ridge, and its fitness centre overlooks the Petanu river valley.'),
    ('maya-ubud-yoga-ubud', '1736d39f6275b666cd471dd5429f4c83', 'Yoga classes at Maya Ubud Resort & Spa are held in a shala that overlooks the Petanu valley.'),
    ('menega-cafe', '98a451e5f710701b4065522aef14016a', 'A seafood cafe on Jimbaran Bay. You pick fresh seafood by weight from the display, and it is grilled over coconut-husk fires. Tables sit directly on the sand of Muaya Beach for dinner at sunset.'),
    ('mercure-bali-sanur-resort-sanur', 'c188843700486528493af261c4464ccd', 'The wellness spa at Mercure Bali Sanur Resort does reflexology and traditional massage, and 45 minutes of reflexology costs 299K IDR. Book on the resort''s own site.'),
    ('moonlite-kitchen-and-bar', '03811b7a32a942c0061f7292187f48a4', 'The rooftop bar and restaurant at Anantara Seminyak Bali Resort serves a modern Southeast Asian menu with ocean views. Live bands and DJ sets play every night.'),
    ('motion-skatepark', '3185b7957581516d57a8610fd7e831df', 'An indoor skatepark on Sunset Road, rebuilt in 2019. The layout is street-style, with transitions around the edge, a mini ramp to one side and obstacles from easy to hard. There is a skate shop on site, and locals will teach if you ask.'),
    ('movenpick-jimbaran-yoga', '2179d24ac86ee09929f29b9c8c3d77c2', U&'Yoga at M\00F6venpick Resort & Spa Jimbaran runs through the 24-hour fitness centre in the Samasta complex. Some classes are free, including the Sunday vinyasa session; others are charged. Pilates runs on the same timetable.'),
    ('movenpick-resort-and-spa-jimbaran-fitness', '21e45a1121d501cda602b7469c3c0af4', U&'The 24-hour gym at M\00F6venpick Resort & Spa Jimbaran has current cardio machines and weight stations. Alongside it runs a class programme of yoga, pilates, aqua aerobics and water volleyball, and you can cycle on the property.'),
    ('naya-uluwatu', '51b6a58989c3a61035a46fe789c49353', 'NAYA runs semi-private pilates in Bingin, Uluwatu. Each class has five reformers, so it stays small.'),
    ('nirvana-life-bali-canggu', '1fa9977e1f50280ac816b80c9c61f039', U&'Nirvana Life is a fitness and wellness club in Berawa, open 6am\201311pm, with a gym, classes and recovery in the same building.'),
    ('noonik-bistro', '1cd6d1b7f8dda2c44fa5c6f45d52c3c2', 'A modern Asian bistro in Mas, Ubud, open daily from 07:00 to 22:30. The menu runs from breakfast to dinner, mixing Asian and Indonesian dishes.'),
    ('nui-da-mano-beachfront-restaurant-in-batu-belig', '4a0d1fcb81f7cb21b032c6927564e04b', 'A Polynesian-inspired restaurant directly on Batu Belig Beach, cooking Polynesian flavours with local ingredients. Seating is open-air, and the food comes as shared plates by the sea.'),
    ('olop-iyengar-yoga', 'd4877a1db3280574ea9f3bab9b7e6f4b', 'Olop is an Iyengar yoga studio in Seminyak, where practice centres on alignment and props.'),
    ('oma-jamu', '2b4b7ce1111a05a164cd1393852760c6', 'A budget vegan cafe and organic grocery near the Puseh temple in Batu Bolong. Plant-based Indonesian food runs all day, alongside cold-pressed juices, kombucha and traditional jamu tonics.'),
    ('padang-padang-surf-camp-uluwatu', '2614fb41515b2ffa334cc2dc66bf8d4d', 'Padang Padang Surf Camp has coached surfers in Bingin since 2005, and its lead coach grew up surfing there.'),
    ('padma-resort-legian-kuta-legian', '2ca1b525db8a1d19abcc1fd4490e6998', 'Padma Resort Legian has a day spa that does hair treatments, and the resort takes bookings on its website.'),
    ('pak-gula', '18373a5a1514daa2986d75019c3b3845', 'PAK GULA is a two-storey restaurant in Bingin from the team behind The Cashew Tree. Sharing plates include char siu pork bao, vegetable dumplings, chicken satay and braised beef curry. Downstairs is casual; upstairs is a low-lit dinner room with communal tables and a bar.'),
    ('pala-spa-munduk', '4f0d741f776ba26ac8a5e97b4bb0417d', 'Pala Spa is a wellness spa in Munduk where you can book a Balinese massage online.'),
    ('pantai-pandawa', '7d39567c5d5467ab6d545c4fccc85e6e', 'A white-sand beach on the Bukit peninsula in Badung. You reach it on a road cut through the cliffs, and statues of the Pandawa brothers line the entrance.'),
    ('paradise-padel-bali', '27cb42c09b0b0d1188d65ab15d251856', 'The padel club on Jalan Subak Sari rents equipment and has parking, a shop, a restaurant and changing rooms. Courts book through Playtomic, and a 60-minute session with a coach starts at 900,000 IDR. Tournaments and mixed-level sessions run regularly.'),
    ('parigata-resorts-and-spa-sanur-bali-sanur', 'fb4a7b265603a72142e95648f1422210', 'Parigata Resorts and Spa in Sanur does Balinese massage and a spa package; bookings are on its own site.'),
    ('piasan-nusa-dua-restaurant-piasan-restaurant', '0da710594cd329df49ad056f5662a821', 'Piasan is an Italian restaurant at Kayumanis, in the BTDC area of Nusa Dua. The dining room is built from over 15,000 bamboo stems, with floating partitions and a raised ceiling. The name comes from a Balinese term for a ceremonial structure.'),
    ('pica-south-american-kitchen', 'f4a0c752fc6914949ecd1d0aa4a4540a', 'A small South American kitchen in central Ubud, cooking Peruvian and South American flavours.'),
    ('pizzaria-hyatt', 'c659ab6cbf573c5e31bfdc25dbc398ef', 'Pizzaria is Hyatt Regency Bali''s beachfront Italian restaurant and bar on Sanur Beach, with sea views. Antipasti, wood-fired sourdough pizza, pasta, seafood and meat are served at lunch and dinner daily. Sunday Brunch adds live grills and carvings.'),
    ('poggy-bali-surf-school-uluwatu', '1088168a363d8998dc7d61dc67da742e', 'A surf school based at Padang Padang beach. It coaches all levels across the Bukit''s breaks, including Padang Padang, Bingin and Dreamland.'),
    ('pole-studio-bali', '5e2673b0f5ab13670fe644bdcd22aa0a', 'At Pole Studio Bali, beginner classes cover spins, climbs and transitions, and intermediate and advanced students work through routines. Flexibility and conditioning classes run alongside, and private lessons are available.'),
    ('prime-plaza-hotel-sanur-fitness-centre', '3e67888da0afaaeaf4c1249d394689be', 'Prime Plaza Hotel Sanur''s gym is open to the public; hotel guests train free. Walk-ins pay 100,000 IDR at peak and 75,000 IDR off peak, which includes a locker, hot and cold showers and spa access. The gym has treadmills and stationary bikes alongside free weights and machines. Personal trainers can be booked ahead by the hour or by the day or week. The property also has a sauna and a hot tub, plus a 110-metre pool.'),
    ('pullman-bali-legian-beach-kuta-legian', '5d7e4e04a42fa4555b428e58d3da1584', 'Pullman Bali Legian Beach has a resort spa for traditional massage; book on the hotel''s own website.'),
    ('reform-pilates-bingin', '3dcb2b6f1e91602ebfff3e53b552cf42', 'A reformer pilates studio in Bingin, opened in 2023 by Abbey. Classes include Booty & Core, Body Blast and deep stretch. Pre- and post-natal reformer classes run for the first and second trimesters. Booking is online.'),
    ('reform-uluwatu', 'abb59c417c3462698139e01056886a51', 'Reform+ is the second Reform Pilates location, in Uluwatu, running reformer classes that you book online.'),
    ('retro-kitchen-and-bar', '2b0e7b4f6ab75a28b8dbf1db225508d4', 'Retro Kitchen and Bar sits on the main Sanur strip and keeps a broad menu. Australian steaks and Western favourites run beside Indonesian dishes, and there is a kids'' section of its own.'),
    ('rip-curl-school-of-surf', '104968d2865a33561a857f3be4073be1', 'Rip Curl''s surf school is on Sanur beach inside the Prama Sanur Beach hotel and has run since 1998. It also teaches kitesurfing, stand-up paddle, windsurfing, wakeboarding, diving and foiling, with certification and rentals. The Little Ripper programme is for under-13s.'),
    ('rockfish-cliffside', '9abbe968cdb1d444fa0f9665abfe1195', 'Rockfish Cliffside is a restaurant on the cliffs in Pecatu, with a menu led by seafood and wagyu.'),
    ('roots-pererenan', 'ea7111c9526c0ceefa2800676300de6c', 'An all-day plant-based restaurant in Pererenan for vegans, vegetarians and anyone eating less meat. The menu is built around a bowl you make yourself from 50+ ingredients.'),
    ('rosehill-spa-nusa-dua', 'b8a4d360c39296897f1f0539aa53e138', 'An hour of foot reflexology costs 300K IDR at Rosehill Spa, a day spa in Nusa Dua that also does traditional massage. Booking is on the spa''s own site.'),
    ('rotisserie-by-cashew-tree', '9a3ff6c4ec18a915bf20dba2dee8cc18', 'The Cashew Tree''s rotisserie in Pecatu slow-roasts meats and serves them with fresh sides and sauces.'),
    ('s2s-crossfit', 'd4cafeec7bcf697d9a21a19a60866f5b', 'S2S is a CrossFit box on Jl. Raya Semat. It runs CrossFit, weightlifting, high-intensity cardio and personal training. A drop-in costs 200,000 IDR with no booking needed; arrive ten minutes before class.'),
    ('sanur-surf-school', '16dcd223579bf88d53792339d19b00bb', 'Sanur Surf School teaches at Baby Reef, a short boat ride offshore, where the waves break smaller and softer than in the south. Lessons are private or semi-private for two, from a first wave to refining technique. Children are welcome, and foiling is taught too.'),
    ('seabird-bistro-and-coworking-canggu-by-wonderspace', '2c3c6b2a32ae1ae03c2e1b0cda92c286', 'Seabird is a bistro and coworking space on Jl. Nelayan, part of the Wonderspace group. The kitchen does Italian comfort food with a French turn, such as grilled lobster tagliatelle, wagyu steak frites and rigatoni vodka. Vegetarian and vegan options sit alongside local wines and cocktails.'),
    ('seasalt', 'ba00887ea0e43896fb4d662907d423cd', 'Seasalt is beachfront fine dining inside Alila, and the menu leads with seafood. Come for a date night by the coast or a brunch splurge.'),
    ('serenity-bali-yogi-spa-canggu', '20f687de044f7ba59cfcd8f6adb4b127', 'Serenity Bali Yogi Spa in Canggu does Balinese massage at 250K IDR for 60 minutes, and bookings run through Fresha.'),
    ('serenity-eco-guesthouse-yoga-canggu', 'bc05309a8e0e0b864c94746d8dad0f51', 'Serenity Eco Guesthouse in Nelayan has a yoga shala with a busy daily timetable. A wellness day pass costs 249k.'),
    ('sista-dumpling', '5f59b9c866da1fd5f7d57524719bf8ba', 'Sista Dumpling is a modern dumpling bistro on Jl. Raya Semat in Berawa, open from late morning to 11pm. The menu is built around sharing plates, with drinks alongside. There is a second branch in Uluwatu; the details here are for the Berawa room.'),
    ('skai-beach-club-legian', '9777684d5536674cd54028878d6f8b79', 'S.K.A.I is the beach club at Padma Resort Legian, with a semi-alfresco terrace and an infinity pool set over the Legian surf. Sunset is the main event.'),
    ('spa-at-rimba-by-ayana-bali-jimbaran', '87e37c3d95e5594387a814871181bd6a', 'The spa at RIMBA by AYANA sits on the vast AYANA estate above Jimbaran, a resort-and-wellness complex.'),
    ('spa-sidemen-sidemen', '946c95de3e1e740a92def445bff41164', 'Spa Sidemen is a massage studio in Sidemen where a 60-minute Balinese massage costs 250K IDR. Book by WhatsApp.'),
    ('st-regis-bali-yoga', 'c44723e1ea7f8d23d4211c3dbf89ab9e', 'The St. Regis Bali Resort runs its yoga and movement programme from a yoga room inside the Iridium Spa. The free schedule covers beachside yoga, stand-up paddle yoga, meditation and Tai Chi in the resort amphitheatre.'),
    ('sunset-pilates-legian', '6cf5e80d806f834e3ecbe25bc59ec726', 'A pilates studio in Legian with a class schedule you can drop into. It is a lower-impact option than yoga for a morning session near the beach.'),
    ('svaha-spa-melasti-uluwatu-bukit', '65b6cb95d6defefb6da54ce5ec667703', 'At Svaha Spa Melasti, a day spa in the Bukit, you can have a Balinese massage or a spa package. Its website takes bookings.'),
    ('swan-restaurant-keramas-desa-swan-villas-and-spa', 'a27bc44bd03c6b3086e521bb6b2cedba', 'Restaurant in Desa Swan Villas and Spa Jalan Pantai Selukat.'),
    ('takk-bali', 'dde115e7ffafdda1f72d1c208e9a5da3', 'TAKK is a casual fine-dining restaurant on Jalan Petitenget, cooking dinner with Bali ingredients. The dishes it lists include sea-salt cured salmon, charred local lamb and a cocoa-and-citrus dessert.'),
    ('tanah-lot', 'd3642633b67427f1f20b6dc09a95d31a', 'Tanah Lot is a sea temple on an offshore rock, framed by the sunset. The inner sanctum is closed to non-worshippers, and you can reach the rock base only at low tide.'),
    ('the-free-bird-studio', 'c5d7925b486e0581e700e848d8c648e1', 'A movement studio in Berawa whose programme covers movement, healing, ceremony and activation.'),
    ('the-garcia-ubud-ubud', 'b3112db310d7b5b424240f29e18666b3', 'The Garcia Ubud is a spa in Ubud where a traditional Balinese massage costs 690K IDR. It takes bookings on its own website.'),
    ('the-jungle-club-ubud-by-wonderspace', '1dc1822af1613a4faf48105704b7c0a9', 'An adults-only day club on roughly two hectares of jungle in Celuk. The grounds hold an infinity pool, a jungle deck, a boho cave and a jetty, and Svaha Spa shares the site. The club also puts on live music and themed events.'),
    ('the-little-hill-terrace', 'bd33d7c0996f2d6ce6fcaefc29a11e75', 'The restaurant at The Little Hill Suites in Munduk cooks with produce sourced from North Bali farms. Its terrace looks over green hills and valleys.'),
    ('the-northview-bali-ngiring-ngewedang-restaurant-and-coffee-c', '369e3cc71d2bb57d1c22a0455082610a', 'A hilltop restaurant and coffee corner in Munduk village, cooking Asian and Indonesian dishes and pouring Balinese coffee and teas. Crispy duck and banana fritters are regulars, and the open dining room faces the hills and valleys.'),
    ('the-sanur-sanur', '5b4634e0f25ce313afbd5fb032d9f462', 'The Sanur, a day spa in Sanur, does Balinese massage and aromatherapy. A 60-minute Balinese massage is 350K IDR; book on the spa''s own site.'),
    ('the-tanjung-benoa-beach-resort-nusa-dua', 'f728a3f092352d51e392528e97914ba8', 'The spa at The Tanjung Benoa Beach Resort in Nusa Dua covers Balinese massage, aromatherapy and facials. A 60-minute Balinese massage costs 450K IDR.'),
    ('the-ungasan-uluwatu-bukit', 'c9cba48f6d2b317507941f8f9de313ab', 'The Ungasan is a wellness spa in the Bukit; message it on WhatsApp to book a facial.'),
    ('tirta-empul', 'a4abfa46873fbe1a2383df7ea0a48fb9', 'A temple built around a sacred spring. Balinese Hindus and visitors perform melukat here, a purification ritual that moves from spout to spout through the bathing pool. A sarong is required and provided at the gate.'),
    ('tirta-padma-tribhuwana-padma', '5985f18ef0f89ab8d3b491cd7e6552ae', 'Tirta Padma is the restaurant at Tribhuwana Padma, a lakeside resort in Kedisan, Kintamani, with views of Mount Batur and the highlands around it.'),
    ('tonic-kuta-legian', 'c90b12063e0db04854de79f823d0c2be', 'Tonic is a wellness spa in Legian for aromatherapy and couple massage. Its Couples Spa Package runs 90 minutes for 750K IDR, and you book on the spa''s own site.'),
    ('tsune-japanese-restaurant-sanur-by-wonderspace', '6b90866e5e94a2efc420299d7bbb8b21', 'Japanese restaurant in Sanur with floating sushi: plates travel to the table along a waterway. A Japanese fish grill runs alongside. Live music on Saturday evenings, and 10% off lunch every day.'),
    ('ubud-bodyworks-centre-ubud', 'bd252b8e689ad23fd08062c18b8df47e', 'Ubud Bodyworks Centre takes WhatsApp bookings for deep tissue massage at its wellness spa.'),
    ('ubud-yoga-centre', '3b2b5fe8f97c2ca1790c702fc3c235b9', 'A hot-yoga studio in a contemporary two-tier complex on the edge of Nyuh Kuning. The complex also has a gong centre, a kids centre and a cafe.'),
    ('urban-seaside-restaurant-and-bar', '7c484af5f98f3dda91af439923bb2755', 'Urban Seaside is a beachfront restaurant on Jalan Segara Samuh in Nusa Dua, open daily from 08:00 to 23:00. The menu runs from the daily fresh catch to international comfort dishes and Asian-influenced flavours.'),
    ('usadha-spa-kuta-legian', '1b5c2b5e2e24e03d48132c3860b8baf1', 'Usadha Spa in Legian takes bookings on its website for Balinese massage.'),
    ('warung-bu-mi', '9c6b615ce1dfb08930ddceab10505ee8', 'A warung in Batu Bolong serving Indonesian home-style food. Its official profile lists service from 09:00 to 22:00 and says all the food is halal.'),
    ('warung-jawa-bu-sri', '42dff0aacf79af5b27418a4aacc044a5', U&'A small family-run warung cooking Javanese-Balinese home-style nasi campur for lunch. It is semi-indoor with street views, open roughly 10am\20135pm and closed on Sundays.'),
    ('warung-varuna', '0a70498cf83c024053c53c298b381024', 'A buffet-style Indonesian warung with 30-plus dishes in a glass case. You build a plate of rice, proteins and vegetables at low prices, any day from 8am to 10pm.'),
    ('warung-yess', '5a5a10f62767d2daa2c13b19533b779e', 'A nasi campur warung in Pererenan with indoor and garden seating. You build a mixed-rice plate from the day''s fresh display, and the warung has its own sambal matah.'),
    ('wild-vegan', '528067e38eb5edb3fc39641bb0832cfa', 'A 100% vegan restaurant in central Ubud, cooking with whole foods and medicinal plants.'),
    ('zahra-spa-nusa-dua-nusa-dua', 'd821057bb8c79ae10a0c8480714d08ec', 'Zahra Spa in Nusa Dua does neck and shoulder treatments, aromatherapy and Balinese massage, which costs 375K IDR. Bookings are made on the spa''s website.'),
    ('zando-fight-camp-uluwatu', 'b6e1847ceadbcf4c73b914df53c204b3', 'Zando Fight Camp is a Muay Thai gym in Ungasan running group and private sessions, from beginner technique to advanced, with pad work and conditioning. A drop-in costs 150,000 IDR and a month 1,600,000.')
  ) as d(slug, old_md5, val)
  where v.slug = d.slug and v.status = 'active' and v.publication_status = 'published'
    and case when d.old_md5 is null then (v.why_its_here is null or length(trim(v.why_its_here)) = 0) else md5(v.why_its_here) = d.old_md5 end;
  get diagnostics n = row_count; if n <> 88 then raise exception 'wave-clean-b-2026-10-08 why_its_here: expected 88 rows, got %', n; end if;

  update venues v set best_for = d.val
  from (values
    ('laddu-restaurant-the-sankara-suites-and-villas', '4cbb9be8ef6eb333bde2bdc9807896b9', 'An all-day Asian-fusion meal in a small resort dining room'),
    ('le-meridien-bali-jimbaran-fitness', 'df3c19cb891886ff1f1e393fc7bd9744', 'Hotel guests who want a workout at any hour, included in the room rate'),
    ('lkp-tirtasari-spa-tabanan', '60d843c4ac2e5d46cc87cd88278b2901', 'A Balinese massage in Tabanan'),
    ('lluvia-spa-seminyak', '1a510b0da01dd9d9bb63391a761453a7', 'Ninety minutes of Japanese head spa in Seminyak'),
    ('lolas-cantina-canggu', 'eefeb1a25527d5edca5cc4de90df4942', 'Casual tacos and cocktails with a group or as a couple'),
    ('lolas-cantina-uluwatu', 'a9cb3eb0434e64267549b3b63af056d0', 'Groups and couples after a casual Mexican meal in Uluwatu'),
    ('luigis-hot-pizza', '0f316fa6476d83fde2c48406121cc54b', 'Pizza and drinks any day from 4pm, or one of the weekly party nights'),
    ('luxme-bali-jimbaran', '20a507156c93cb492815bc27cf0c7453', 'A four hands massage in Jimbaran'),
    ('luxury-spa-nusa-dua', '8996f61ea985a9aac375448bf0bf0ee5', 'Pilates at a Nusa Dua day spa'),
    ('m-boutique-resort-uluwatu-bukit', 'ea463111011a261a6ef75c165d63587d', 'Yoga at a boutique resort in the Bukit'),
    ('mandapa-fitness-centre', '1bf1faa7e9d0f22417b7dd47c3d0b5d1', 'Resort guests who want the gym at any hour and yoga above the rice terraces'),
    ('mantra-wellness-bali-uluwatu-bukit', '60d843c4ac2e5d46cc87cd88278b2901', 'Massage or yoga at a wellness spa in the Bukit'),
